window.products.push({"id":1031086,"name":"Elements Nailhead Resin Candle Holder (6-Inch/8-Inch/10-Inch, Silver, Set of 3)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51hxMEan99L._AC_.jpg","description":"Add lustrous, ambient light to your home with this Elements Nailhead Resin Candle Holder set. These candle holders feature a beautiful antique silver finish, and make an excellent addition to the home. This set consists of one (1) 10-inch, one (1) eight-inch and one (1) six-inch candle holder. These candle holders may be grouped together or dislayed separately to add ambiance to any room. Candles are not included with this set.","images":["https://m.media-amazon.com/images/I/51hxMEan99L._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Elements","source_asin":"B00F2ZH8PI","category_path":"Home & Kitchen"},"sku":"BM-1031086","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00F2ZH8PI","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00F2ZH8PI","price_pending":true,"merchant_ready":false});
